-- 球场 + 区导入（tools/venues_seed.mjs 生成，请勿手改）。可重复执行。
-- 位置：GEO_OK 的球场来自 OpenStreetMap（© OpenStreetMap contributors，ODbL）；其余为区中心估值（geo_source = suburb_centroid，待核实）。
-- 区的邮编来自 matthewproctor/australianpostcodes。
begin;

on conflict (name, postcode) do nothing;

on conflict on constraint venues_short_name_suburb_pc_key do nothing;

commit;
